"""Text-to-SQL harness: draft query, execute-check, one diagnostic repair call if needed.

Contract (fixed): solve(task, env) -> {"sql": str}
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
IDENT = re.compile(r"\b(?:FROM|JOIN)\s+[\"'`\[]?([A-Za-z_][A-Za-z0-9_]*)", re.I)
CREATE_RE = re.compile(
    r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?[\"'`\[]?([A-Za-z_][A-Za-z0-9_]*)[\"'`\]]?\s*\((.*)\)\s*;",
    re.S | re.I,
)
COL_RE = re.compile(r"^\s*[\"'`\[]?([A-Za-z_][A-Za-z0-9_]*)[\"'`\]]?\s+"
                    r"(?:INT|INTEGER|TINYINT|SMALLINT|BIGINT|REAL|FLOAT|DOUBLE|DECIMAL|NUMERIC|"
                    r"TEXT|CHAR|VARCHAR|NCHAR|NVARCHAR|CLOB|BLOB|BOOL|BOOLEAN|DATE|TIME|TIMESTAMP)", re.I)
FK_RE = re.compile(r"FOREIGN\s+KEY\s*\(\s*[\"'`\[]?([A-Za-z_][A-Za-z0-9_]*)[\"'`\]]?\s*\)\s*"
                   r"REFERENCES\s+[\"'`\[]?([A-Za-z_][A-Za-z0-9_]*)[\"'`\]]?\s*"
                   r"\(\s*[\"'`\[]?([A-Za-z_][A-Za-z0-9_]*)[\"'`\]]?\s*\)", re.I)
LIT_EQ_RE = re.compile(r"([A-Za-z_][A-Za-z0-9_]*)\s*(?:=|LIKE)\s*'([^']*)'", re.I)


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


def _tables(sql):
    seen = []
    for t in IDENT.findall(sql or ""):
        if t.lower() not in ("select",) and t not in seen:
            seen.append(t)
    return seen


def _schema_map(env, db_id):
    """table -> (create statement, [column names]) parsed from the shipped schema."""
    try:
        text = env.schema(db_id) or ""
    except Exception:
        return {}
    out = {}
    for m in CREATE_RE.finditer(text):
        name, body = m.group(1), m.group(2)
        cols = []
        for line in body.splitlines():
            cm = COL_RE.match(line)
            if cm and cm.group(1).lower() not in ("primary", "foreign", "unique", "check", "constraint"):
                cols.append(cm.group(1))
        out[name] = (m.group(0).strip(), cols)
    return out


def _exec(env, sql, n):
    try:
        r = env.execute(sql, max_rows=n)
    except Exception:
        return None
    if isinstance(r, dict) and r.get("ok"):
        return r
    return None


def _fmt(vals, cap=10):
    shown = [repr(v) for v in vals[:cap]]
    if len(vals) > cap:
        shown.append("...")
    return ", ".join(shown)


def _diagnostics(env, task, sql, limit_tables=4):
    """Schema-derived facts about the draft: real column names/FKs and real stored values."""
    smap = _schema_map(env, task["db_id"])
    tabs = _tables(sql)[:limit_tables]
    low = {t.lower(): t for t in smap}
    parts = []

    # 1. For each string literal compared in the draft, show what is actually stored there.
    probed = set()
    for col, lit in LIT_EQ_RE.findall(sql or ""):
        key = (col.lower(), lit)
        if key in probed:
            continue
        probed.add(key)
        owners = [t for t in tabs if any(c.lower() == col.lower() for c in smap.get(low.get(t.lower(), t), ("", []))[1])]
        if not owners:
            owners = [t for t, (_, cols) in smap.items() if any(c.lower() == col.lower() for c in cols)]
        for t in owners[:2]:
            r = _exec(env, f'SELECT DISTINCT "{col}" FROM "{t}" WHERE "{col}" LIKE \'%{lit}%\' LIMIT 8', 8)
            if r and r.get("rows"):
                parts.append(f"Stored values in {t}.{col} containing {lit!r}: " + _fmt([row[0] for row in r["rows"]], 8))
            else:
                r2 = _exec(env, f'SELECT DISTINCT "{col}" FROM "{t}" LIMIT 12', 12)
                if r2 and r2.get("rows"):
                    parts.append(f"No value in {t}.{col} contains {lit!r}. Actual distinct values: " + _fmt([row[0] for row in r2["rows"]], 12))

    # 2. Real schemas of referenced tables + value profile of columns used in filters.
    filter_cols = {c.lower() for c, _ in LIT_EQ_RE.findall(sql or "")}
    for t in tabs:
        real = low.get(t.lower(), t)
        info = smap.get(real)
        if info:
            parts.append(info[0])
        for c in (info[1] if info else []):
            if c.lower() not in filter_cols:
                continue
            r = _exec(env, f'SELECT "{c}", COUNT(*) FROM "{real}" GROUP BY "{c}" ORDER BY COUNT(*) DESC LIMIT 12', 12)
            if r and r.get("rows"):
                parts.append(f"Value counts for {real}.{c}: " + _fmt([tuple(row) for row in r["rows"]], 12))

    # 3. Foreign keys linking referenced tables (fixes invented join columns).
    refs = {t.lower() for t in tabs}
    for t in tabs:
        real = low.get(t.lower(), t)
        info = smap.get(real)
        if not info:
            continue
        for c, rt, rc in FK_RE.findall(info[0]):
            if rt.lower() in refs:
                parts.append(f"Foreign key: {real}.{c} -> {rt}.{rc}")
    return "\n".join(parts)[:3500]


def solve(task, env):
    user = (
        f"Database: {task['db_id']}\n\nSchema:\n{env.schema(task['db_id'])}\n\nQuestion: {task['question']}"
    )
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        pass
    if desc:
        user += f"\nColumn descriptions:\n{desc[:2000]}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    sql = extract_sql(reply)

    # Verify draft; repair once on error or empty result.
    try:
        res = env.execute(sql, max_rows=5)
    except Exception:
        res = {"ok": False, "error": "execution failed", "rows": [], "n_rows": 0}

    needs_repair = (not res.get("ok")) or res.get("n_rows", 0) == 0
    if needs_repair:
        if not res.get("ok"):
            feedback = f"The query failed with error: {res.get('error')}"
        else:
            feedback = (
                "The query executed but returned 0 rows. Likely causes: a string literal does not "
                "match stored values (case/spacing/format), a wrong join column or join direction, "
                "or an over-restrictive filter. Use the database facts below to find the real column "
                "names, foreign keys and stored values."
            )
        diag = _diagnostics(env, task, sql)
        repair_user = (
            f"{feedback}\n\nYour draft query:\n```sql\n{sql}\n```\n"
            + (f"\nDatabase facts (exact schemas, stored values, foreign keys):\n{diag}\n" if diag else "")
            + "\nRe-examine the question and schema above, then output ONE corrected SQLite query "
              "in a single ```sql code block. Keep the projection faithful to the question: if it "
              "asks which entities qualify ('which countries/students...', 'details of ...'), return "
              "the entity table's full row (SELECT T1.*); if it names specific attributes (e.g. "
              "'first, middle and last names', 'ids of ...'), select exactly those columns, no more."
        )
        messages = messages + [
            {"role": "assistant", "content": reply},
            {"role": "user", "content": repair_user},
        ]
        try:
            reply2 = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
            sql2 = extract_sql(reply2)
            if sql2:
                try:
                    res2 = env.execute(sql2, max_rows=5)
                except Exception:
                    res2 = {"ok": False}
                # Prefer the repaired query if it runs; keep draft if repair errors.
                if res2.get("ok"):
                    sql = sql2
        except Exception:
            pass

    return {"sql": sql}

